    # Classic 'mort' state tables, see Apple's TrueType Reference Manual,
    # chapter "The 'mort' table". All offsets are byte offsets from the
    # start of the state table header, and new states are byte offsets
    # of state array rows.

    def _classicEntrySize(self):
        if issubclass(self.tableClass, (ContextualMorphAction, InsertionMorphAction)):
            return 8
        return 4

    def _classicHeaderSize(self):
        if issubclass(self.tableClass, ContextualMorphAction):
            return 10  # plus substitutionTable
        if issubclass(self.tableClass, LigatureMorphAction):
            return 14  # plus ligActionTable, componentTable, ligatureTable
        return 8

    @staticmethod
    def _readClassicArray(reader, typecode, itemSize, count):
        if count < 0 or reader.pos + count * itemSize > len(reader.data):
            raise ValueError("'mort' state table is truncated")
        return reader.readArray(typecode, itemSize, count)

    def _readClassic(self, reader, font):
        start = reader.pos
        size = len(reader.data) - start

        def readerAt(offset):
            subReader = reader.getSubReader(0)
            subReader.seek(start + offset)
            return subReader

        table = AATStateTable()
        stateSize = reader.readUShort()
        classTableOffset = reader.readUShort()
        stateArrayOffset = reader.readUShort()
        entryTableOffset = reader.readUShort()
        if stateSize == 0:
            raise ValueError("'mort' state table has no glyph classes")
        if stateArrayOffset > entryTableOffset:
            raise ValueError("'mort' state array starts after the entry table")
        table.GlyphClassCount = stateSize

        classReader = readerAt(classTableOffset)
        firstGlyph = classReader.readUShort()
        numGlyphs = classReader.readUShort()
        classes = self._readClassicArray(classReader, "B", 1, numGlyphs)
        glyphs = font.getGlyphNameMany(range(firstGlyph, firstGlyph + numGlyphs))
        table.GlyphClasses = dict(zip(glyphs, classes))

        if issubclass(self.tableClass, ContextualMorphAction):
            substitutionOffset = reader.readUShort()
        elif issubclass(self.tableClass, LigatureMorphAction):
            reader.readUShort()  # ligActionTable; entries locate their actions
            componentOffset = reader.readUShort()
            ligatureOffset = reader.readUShort()
            self._readClassicLigatureTables(
                table, font, readerAt, componentOffset, ligatureOffset, size
            )

        def readTransition(entryIndex):
            entryOffset = entryTableOffset + entryIndex * self._classicEntrySize()
            transition = self._readClassicEntry(
                readerAt(entryOffset), font, readerAt, table
            )
            transition.NewState = (transition.NewState - stateArrayOffset) // stateSize
            return transition

        stateReader = readerAt(stateArrayOffset)
        numStates = (entryTableOffset - stateArrayOffset) // stateSize
        for _ in range(numStates):
            state = AATState()
            row = self._readClassicArray(stateReader, "B", 1, stateSize)
            for glyphClass, entryIndex in enumerate(row):
                state.Transitions[glyphClass] = readTransition(entryIndex)
            table.States.append(state)

        if issubclass(self.tableClass, ContextualMorphAction):
            self._readClassicSubstitutions(
                table, font, readerAt, substitutionOffset, size
            )
        return table

    def _readClassicEntry(self, entryReader, font, readerAt, table):
        transition = self.tableClass()
        if issubclass(self.tableClass, (RearrangementMorphAction, ContextualMorphAction)):
            # Same layout as in 'morx'; NewState and the contextual
            # substitution offsets are resolved by the caller.
            transition.decompile(entryReader, font, None)
        elif issubclass(self.tableClass, LigatureMorphAction):
            transition.NewState = entryReader.readUShort()
            flags = entryReader.readUShort()
            transition.SetComponent = bool(flags & 0x8000)
            transition.DontAdvance = bool(flags & 0x4000)
            actionOffset = flags & 0x3FFF
            if actionOffset:
                transition.Actions = transition._decompileLigActions(
                    readerAt(actionOffset), 0
                )
                for action in transition.Actions:
                    action.GlyphIndexDelta -= table._componentWordOffset
        else:
            transition.NewState = entryReader.readUShort()
            flags = entryReader.readUShort()
            transition.SetMark = bool(flags & 0x8000)
            transition.DontAdvance = bool(flags & 0x4000)
            transition.CurrentIsKashidaLike = bool(flags & 0x2000)
            transition.MarkedIsKashidaLike = bool(flags & 0x1000)
            transition.CurrentInsertBefore = bool(flags & 0x0800)
            transition.MarkedInsertBefore = bool(flags & 0x0400)
            for attr, count in (
                ("CurrentInsertionAction", (flags & 0x03E0) >> 5),
                ("MarkedInsertionAction", flags & 0x001F),
            ):
                offset = entryReader.readUShort()
                if count:
                    glyphIDs = self._readClassicArray(readerAt(offset), "H", 2, count)
                    setattr(transition, attr, font.getGlyphNameMany(glyphIDs))
        return transition

    def _readClassicLigatureTables(
        self, table, font, readerAt, componentOffset, ligatureOffset, size
    ):
        if componentOffset > ligatureOffset:
            raise ValueError("'mort' component table starts after the ligature table")
        if (ligatureOffset - componentOffset) % 2 or componentOffset % 2:
            raise ValueError("'mort' component table has an odd length or offset")
        numComponents = (ligatureOffset - componentOffset) // 2
        components = self._readClassicArray(
            readerAt(componentOffset), "H", 2, numComponents
        )
        if any(c % 2 for c in components):
            raise ValueError("'mort' component table holds an odd value")
        # Classic components are byte offsets whose sum, for each ligature,
        # includes the ligature table offset exactly once.
        rebase = {i for i, c in enumerate(components) if c >= ligatureOffset}
        table.LigComponents = [
            (c - ligatureOffset if i in rebase else c) // 2
            for i, c in enumerate(components)
        ]
        table.MortLigatureRebase = rebase
        numLigatures = max(0, (size - ligatureOffset) // 2)
        ligatures = self._readClassicArray(
            readerAt(ligatureOffset), "H", 2, numLigatures
        )
        table.Ligatures = font.getGlyphNameMany(ligatures)
