        table._componentWordOffset = componentOffset // 2

    def _readClassicSubstitutions(self, table, font, readerAt, substOffset, size):
        # Entries hold signed word offsets; offset + glyph ID is the word
        # position of that glyph's replacement. Zero means no substitution.
        toSigned = lambda v: v - 0x10000 if v >= 0x8000 else v
        transitions = [t for s in table.States for t in s.Transitions.values()]
        offsets = sorted(
            {toSigned(v) for t in transitions for v in (t.MarkIndex, t.CurrentIndex)}
            - {0}
        )
        lookupIndex = {offset: i for i, offset in enumerate(offsets)}
        for t in transitions:
            t.MarkIndex = lookupIndex[toSigned(t.MarkIndex)] if t.MarkIndex else 0xFFFF
            t.CurrentIndex = (
                lookupIndex[toSigned(t.CurrentIndex)] if t.CurrentIndex else 0xFFFF
            )
        numGlyphs = len(font.getGlyphOrder())
        table.PerGlyphLookups = []
        for offset in offsets:
            first = max(0, -(-substOffset // 2) - offset)
            limit = min(numGlyphs, size // 2 - offset)
            lookup = {}
            if first < limit:
                values = self._readClassicArray(
                    readerAt(2 * (offset + first)), "H", 2, limit - first
                )
                glyphs = font.getGlyphNameMany(range(first, limit))
                lookup = dict(zip(glyphs, font.getGlyphNameMany(values)))
            table.PerGlyphLookups.append(lookup)

    def _compileClassic(self, font, table):
        stateSize = self._countGlyphClasses(table)
        if not 0 < stateSize <= 256:
            raise ValueError("'mort' state tables need 1 to 256 glyph classes")
        headerSize = self._classicHeaderSize()

        classTable = self._compileClassicClassTable(font, table.GlyphClasses)
        stateArrayOffset = headerSize + len(classTable)
        newStateOffset = lambda t: stateArrayOffset + t.NewState * stateSize

        entryIndices, entryTransitions, stateArray = {}, [], bytearray()
        for state in table.States:
            for glyphClass in range(stateSize):
                transition = state.Transitions[glyphClass]
                key = self._classicEntryKey(transition, newStateOffset(transition))
                entryIndex = entryIndices.get(key)
                if entryIndex is None:
                    entryIndex = entryIndices[key] = len(entryTransitions)
                    entryTransitions.append(transition)
                if entryIndex > 0xFF:
                    raise ValueError("'mort' state tables allow at most 256 entries")
                stateArray.append(entryIndex)
        if stateSize > 1:  # padding must not look like another state
            stateArray = pad(bytes(stateArray), 2)
        entryTableOffset = stateArrayOffset + len(stateArray)
        dataOffset = entryTableOffset + len(entryTransitions) * self._classicEntrySize()

        header = struct.pack(
            ">4H", stateSize, headerSize, stateArrayOffset, entryTableOffset
        )
        if issubclass(self.tableClass, ContextualMorphAction):
            dataOffset += dataOffset % 2
            extraHeader, entries, data = self._compileClassicContextual(
                font, table, entryTransitions, newStateOffset, dataOffset
            )
        elif issubclass(self.tableClass, LigatureMorphAction):
