            return struct.pack(">HH", 0, 0)
        classes = {font.getGlyphID(g): c for g, c in glyphClasses.items()}
        firstGlyph = min(classes)
        numGlyphs = max(classes) - firstGlyph + 1
        classArray = bytes(classes.get(firstGlyph + i, 1) for i in range(numGlyphs))
        return pad(struct.pack(">HH", firstGlyph, numGlyphs) + classArray, 2)

    @staticmethod
    def _compileWithFields(font, transition, **fields):
        transition = copy.copy(transition)
        transition.__dict__.update(fields)
        writer = OTTableWriter()
        transition.compile(writer, font, None)
        return writer.getAllData()

    def _classicEntryKey(self, transition, newStateOffset):
        if issubclass(self.tableClass, LigatureMorphAction):
            return (
                newStateOffset,
                transition.SetComponent,
                transition.DontAdvance,
                transition.ReservedFlags,
                transition.compileLigActions(),
            )
        if issubclass(self.tableClass, InsertionMorphAction):
            return (
                newStateOffset,
                tuple(transition._FLAGS and [getattr(transition, f) for f in transition._FLAGS]),
                tuple(transition.CurrentInsertionAction),
                tuple(transition.MarkedInsertionAction),
            )
        if issubclass(self.tableClass, ContextualMorphAction):
            return (
                newStateOffset,
                transition.SetMark,
                transition.DontAdvance,
                transition.ReservedFlags,
                transition.MarkIndex,
                transition.CurrentIndex,
            )
        return (newStateOffset, transition.MarkFirst, transition.DontAdvance,
                transition.MarkLast, transition.ReservedFlags, transition.Verb)

